using Wysicraft.Core;
using Wysicraft.Models;
namespace Wysicraft.Designer;

// get_schema: everything an assistant needs to author projects, including sprites, shapes, sounds, and the
// web and desktop (advanced) tools with the Minecraft compatibility rules.
public partial class MainWindow
{
    static readonly string[] McpEditKinds = ["add_component_template", "create_component", "place_component", "update_component", "detach_component", "arrange", "set_project",
        "upsert_screen", "delete_screen", "upsert_element", "delete_element", "rename_element", "reorder_element", "add_group", "put_script", "delete_script", "delete_asset",
        "set_event", "set_main", "upsert_input", "delete_input", "upsert_animation", "delete_animation", "upsert_state_graph", "delete_state_graph", "upsert_shader", "delete_shader", "upsert_particles", "delete_particles", "add_component", "remove_component"];

    string McpSchema() => Json.Write(new
    {
        controls = Registry.Controls.Values,
        clientActions = Registry.ClientActions, serverActions = Registry.ServerActions,
        screenEvents = Registry.ScreenEvents, advancedScreenEvents = Registry.AdvancedScreenEvents, advancedElementEvents = Registry.AdvancedElementEvents,
        elementDefaults = new Element(), screenDefaults = new UiDefinition(), eventDefaults = new UiEvent(), projectDefaults = new Manifest(),
        inputDefaults = new GameInput(), animationDefaults = new ScreenAnimation { Tracks = [new() { Keys = [new()] }] }, colliderPointDefaults = new Vertex(),
        targets = new { both = "Minecraft and web & desktop (default): everything allowed; Minecraft exports list what Minecraft can't run", minecraft = "Minecraft only: Minecraft limits are errors, advanced tools hidden", web = "Web & desktop only: advanced tools and larger limits" },
        limits = new { minecraft = Limits.Minecraft, web = Limits.Web },
        shapes = Shapes.Names, keyNames = Validation.KeyNames.Order(), gamepadButtons = Registry.GamepadButtons, gamepadAxes = Registry.GamepadAxes, touchActions = Registry.TouchActions,
        soundFormats = SoundAssets.Extensions, animationProperties = new[] { "x", "y", "width", "height", "opacity", "rotation", "scale" }, eases = new[] { "linear", "ease_in", "ease_out", "ease_in_out", "step" },
        bodies = new[] { "", "static", "dynamic", "kinematic" }, colliders = new[] { "box", "circle", "polygon" },
        components = Behaviours.All.Select(b => new { b.Id, b.Name, b.Group, b.What, b.Adds, script = Behaviours.ScriptOf(b.Id) != null }),
        particlePresets = Particles.Presets, particleEmissions = Particles.Emissions, particleShapes = Particles.Shapes, particleBlends = Particles.Blends,
        particleDefaults = Particles.Preset("sparks", new Random(1)),
        scriptApi = ApiSnippets, arrangeOperations = Enum.GetNames<ArrangeOperation>(), componentStarters = ComponentStarters.All, editKinds = McpEditKinds,
        exportFormats = new[] { "jar", "installation", "standard", "kubejs", "kubejs_files", "web_folder", "web_file", "windows_app" },
        instructions = "Leaderboard pages for Arcadia (project.leaderboards; never part of the game): new_leaderboard key=id data={title, starter: true|false} (the starter has a title, period tabs, podium, top 10, your rank and a player count); upsert_leaderboard screen=id data={title, size:{width,height}}; delete_leaderboard key=id. Element edits (upsert_element, delete_element, arrange...) take screen=<leaderboard id>. A page holds label, image, panel, shape and the widgets lb_table (board:{count 1-100, rowHeight, header, icon, altColor, highlightColor, empty}), lb_podium (top 3), lb_rank (board.rank 1-3), lb_icon (board.rank sets gold/silver/bronze, board.icon crown|medal|trophy|star, or a texture), lb_range (minimum/maximum = the from/to ranks players can change; board.search adds a find-a-player box), lb_slider (board.count, visible 1-5, seconds), lb_me (the viewer and board.around either side) and lb_periods (board.periods \"all,week,day\", periodLabels \"All time|This week|Today\"). A widget's text is a row template: {rank} {name} {score} {runs} {playerNo} {when} {stat.<key>} {medal}; | splits columns, \n starts a new line (podium, rank boxes, slider). Labels can use {title} {label} {players} {period}. Colours are #RRGGBB or #AARRGGBB. The page reads the arcade's board itself (one top(100) shared by every widget) and shows sample players outside Arcadia. arcadia_publish settings leaderboardPage picks it: \"\" (the first leaderboard), \"standard\" or \"board:<id>\". " +
            "add_component_template uses key=one of componentStarters IDs and creates an editable source copy with a unique ID. Components: create_component uses screen, key=new source ID, data={ids:[selected IDs]}; place_component uses screen, key=source ID, data={x,y}; update_component uses screen, element=instance root ID, data={reset:false}; detach_component uses screen, element=root ID. Edit source screens through upsert_element then explicitly update instances. Read get_project for revision. apply_edits uses a list of {kind,screen,element,key,source,data}. data recursively patches existing objects; arrays replace. An upsert therefore keeps fields it is not given: pass replace:true to build the object from defaults plus the data instead, so what you send is exactly what results. upsert_element also takes at:front|back|<index> for where a NEW control sits in the draw order (default front, which draws over everything; later controls draw on top). put_script uses key=path and source=JS; set_event uses key=event name and data={client:{script,function,scriptEngine},server:{...}}. Omit element for screen events. set_main uses screen. Sounds: sound_effect makes retro effects (presets coin, jump, laser, explosion, powerup, hurt, blip, random), compose_music writes layered 8-bit songs from note text (\"C4 q E4 e | G4 h\") and read_music reads them back; both save a sound ID for Sound controls, play_sound and ctx.client.playSound, and the Music maker and Sound effect maker can open them again. Cameras (web & desktop): a camera control is the view; only what is inside the first visible camera is shown, scaled to fill the screen (smaller = zoomed in), and nothing outside it is drawn or clicked. Scripts scroll it with ui.setPosition(id,x,y) and zoom with ui.setSize(id,w,h); animations can move and resize it. Controls with parent set to the camera move with it (a HUD that stays in view); put the camera first in the element list so they can draw at any depth after it. Screens with clipToScreen:true draw and click nothing outside their own size (for games that scroll things in from off screen; upsert_screen data={clipToScreen:true}). arrange uses screen and data={ids:[element IDs],operation:one of arrangeOperations}; full groups and containers move as units. One batch is one Undo. set_project patches manifest fields and remaps asset namespaces when the project ID changes; literal IDs inside scripts must be updated by the author. Item List value is a JSON array of {item,count,name}; ui.setItems updates it. Nested groups use screen.groupParents (child group to parent group) and element.layerGroup. Nested panel parenting uses element.parent with absolute screen coordinates. Item List rowTemplate references a screen containing up to 64 display controls/nested panels. Row buttons use rowAction=item_click/item_primary/item_secondary, handled by the owning list events with the row index. Bind row text/item/value using ${row.item}, ${row.name}, ${row.count}, ${row.index}. rowElements is compiled at export; edit the referenced screen instead. "
            + "IDs: new element IDs are simple numbered names (button1, star1). rename_element uses screen, element=old ID, key=new ID and updates children, action targets and animation tracks (IDs inside scripts are not changed). reorder_element uses screen, element and key=front|back|forward|backward (later elements draw on top). add_group uses screen and key=group name (an empty layer group; data={parent} optional); put elements in it with upsert_element data={layerGroup}. "
            + "Made for: set_project data={target:'minecraft'|'web'|'both'}. validate_project marks issues minecraftOnly:true when they only block Minecraft exports and lists minecraftUses (what Minecraft can't run and where); web_folder, web_file, windows_app and export_electron_apps ignore those. Limits per target are in limits. "
            + "Standard controls that also work in Minecraft: sprite (texture=sheet, frameWidth, frameHeight, clips like 'idle: 0; run: 1-6 @12; jump: 7,8,9 @8 once', value=clip playing; ui.play(id, clip) switches); shape (shape=one of shapes, background or texture fill, borderWidth/borderColor, optional text, click event); sound (no picture, listed in Layers: sound=sound ID, autoplay, delay ms after the screen opens, volume 0-1, repeat times, loop; set its value to 'play' or 'stop' to control it). "
            + "Sounds: import_asset a .ogg/.mp3/.wav/.m4a/.aac file to get a sound ID (projectid:name) for play_sound actions (value=sound ID) and sound controls; Minecraft only plays .ogg, and minecraft:... sound IDs only play in Minecraft. import_asset a name.png.mcmeta to animate an imported name.png (Minecraft animation format: frames stacked, frametime in ticks). "
            + "Advanced (web & desktop only, control advanced:true or these fields): physics: screen gravity (px/s^2), element body static|dynamic|kinematic, collider box|circle|polygon with colliderPoints [{x,y,curve}] relative to the element's top-left (curve:true points are curve handles; outlines must be closed and not cross), bounce and friction 0-1, layer 0-15 and collidesWith (a bit mask over layers, -1 = all: a hitbox on its own layer never reports hitting another hitbox); the collider control is an invisible static wall. Element events collide/collide_stay/collide_end give the other element ID as value (stay repeats every 250 ms while touching). "
            + "trigger:true makes a body or collider a trigger: it passes through things and reports trigger_enter/trigger_stay/trigger_exit (other element ID as value, stay every 250 ms) on both controls; the one entering needs a body (kinematic for script-moved controls) and a trigger pair needs something dynamic or kinematic. "
            + "Components (web & desktop): the editor shows physics as cards — Collider (body set: shape, trigger, layer) and Rigidbody (body dynamic|kinematic: bounce, friction) — plus script components listed in components. add_component uses screen, element and key = collider | rigidbody | one of the components IDs (character_controller, topdown_mover, follower, pickup, and the presets static_body, kinematic_body, trigger_zone, bouncy, slippery); it sets the same fields a person's click would, creates any inputs it needs, and for a script component writes scripts/client/<element>_<suffix>.js, wires its event and records the ID in the element's behaviours list. Its script is never overwritten if it already exists. remove_component with the same key: collider clears the body, rigidbody makes it static, a script component unwires its event and deletes the script if it is still exactly as written (an edited one is kept). The numbers a script component asks you to tune are the var NAME = value; lines above its first function (SPEED, JUMP, GROUND_GRIP, TARGET_TAG, WORTH); change them with put_script, keeping those lines in that form so the card in the editor still shows them. "
            + "Illustrated art (web & desktop): set_project data={smoothImages:true} scales pictures smoothly instead of with hard pixel edges (leave it off for pixel art). Any control has rotation (degrees, clockwise) and scale (1 = its own size) about its centre, and a panel carries what is attached inside it, so a card is a panel with a picture and labels inside. A label or button with wrap:true breaks its text into lines at its width and at \\n. Scripts: ui.setRotation(id,degrees), ui.setScale(id,scale), ui.setOpacity(id,0-1), ui.bringToFront(id), ui.sendToBack(id), ui.moveAbove(id,other), ui.moveBelow(id,other); getElement also gives rotation, scale and opacity. Animations can run rotation and scale. Bodies and colliders are not turned. "
            + "Scripts use ui.setVelocity(id,vx,vy), ui.setPosition(id,x,y), ctx.ui.getElement(id) {x,y,width,height,vx,vy,visible,frame,clip,clipStep,clipDone}, ctx.physics.touching(id) (IDs it touches or overlaps) and ctx.physics.isTouching(a,b). Web & desktop crowds: ui.spawn(template,x,y,{vx,vy,seek,speed,path,separate,life,clip,texture,after}) returns a copy's ID; the engine moves (velocity or seek), collides and expires copies, and each copy runs the template's events as itself; ui.despawn(id), ui.seek(id,target,speed,{path}), ui.separate(id or template,px), ui.instancesOf(template); 5000 at most. path = a tilemap to find the way over; separate = spacing between copies. The template can be a component (its controls copied under a new root as root_ID, moved and despawned through the root). ctx.physics.raycast(x1,y1,x2,y2,{triggers,ignore,tag}) -> null or {id,x,y,distance,normal}; ctx.physics.canSee(a,b); ctx.physics.findPath(map,x1,y1,x2,y2) -> tile centres or null. "
            + "Animations: upsert_animation uses screen, key=animation ID, data={duration ms, loop, autoplay, tracks:[{target element ID, property x|y|width|height|opacity, keys:[{time ms, value, ease}]}]}; delete_animation uses screen and key. Scripts play them with ui.animate(id) and ui.stopAnimation(id); the screen's animation_end event gets the animation ID. "
            + "State graphs (web & desktop): a sprite state machine, so idle -> run -> jump -> land needs no script. upsert_state_graph uses screen, key=graph ID and data={target (a sprite control), start (a state name; empty means the first), states:[{name, clip (a clip on that sprite), transitions:[{to, when, priority}]}]}; delete_state_graph uses screen and key. when is an ordinary condition over the screen variables plus clipDone (the clip has finished), clipStep (how many frames in) and input:name (that input is held) — for example \"clipDone\", \"input:jump\", \"!input:move\", \"hp < 20 && clipDone\"; an empty when is always true. The highest priority that is true wins and at most one transition is taken per frame. Entering a state restarts its clip. The control gets a state_changed event with the new state name, ctx.ui.getElement(id).state reports it, and ui.setState(graphId, state) forces one. At most 64 graphs a screen, 64 states each, 16 ways out of a state. "
            + "Inputs: upsert_input uses key=input name and data={keys:[keyNames], buttons:[gamepadButtons], axis:one of gamepadAxes like 'left_x-' (stick pushed left)}; pad:-1 for any controller or 0-3 for one (two players need one each), touch:one of touchActions (a drag that way on a touch screen presses it, from wherever the finger lands, reporting 0-1 through ctx.input.axis)}; delete_input uses key. Element touchOnly:true draws a control only on a touch device, so on-screen buttons stay off a desktop; ctx.input.isTouch() reports the same thing to a script, and the touch_controls component starter is a ready-made set of buttons. Screens get input_pressed/input_released events with the input name as value; scripts use ctx.input.isDown(name) and ctx.input.axis(name) (0-1), and ctx.input.pointer() -> {x,y,down,presses} for tap-to-move / follow-the-finger (screen coordinates; the latest finger or mouse press that missed the controls, which works on desktop too; presses counts them so a quick tap is not missed; sprites, images, labels and panels do not block it); element input=name makes pressing the control also press the input (its own click and hover events still fire). "
            + "Particles (web & desktop): upsert_particles uses key=effect name and data={emission:burst|stream, count (per burst, or per second for a stream), duration s (stream only, 0=until stopped), life s, lifeVariance 0-1, direction degrees clockwise from east, spread degrees (360=all round), speed px/s, speedVariance 0-1, gravity px/s^2 (positive is down), drag per second, radius px (0=a point), sizeStart, sizeEnd, sizeVariance, colors:[{at 0-1 through the particle's life, color #RRGGBB}] (2-8 stops, the colour ramp; colorStart/colorEnd are the older pair and are used only when colors is empty), opacityStart, opacityEnd, spin deg/s, shape:square|circle|line|texture, texture, blend:normal|add}; delete_particles uses key. particleDefaults shows every field with a working value. Add a particles control (advanced) with effect=name and autoplay; it is invisible and throws from its middle. Fire one with a set_value action of play, stop or clear, or ui.emit(id) and ui.stopEmit(id) from a script; ui.burst(effect, controlId) (or effect, x, y) bursts any effect once with no Particles control (a Pickup component does this with its PARTICLES setting). Move the emitter with ui.setPosition(id,x,y) before emitting to throw from anywhere. At most 2000 particles are alive per screen. "
            + "Tilemaps (web & desktop): the tilemap control draws a grid from one tile sheet. texture = the sheet, tileWidth/tileHeight = one tile in it (tiles are numbered left to right, top to bottom from 0), columns/rows = the map's size (at most 512 each way and 65536 cells), tiles = the grid run-length encoded as space-separated \"index\" or \"index*count\" with -1 for empty (\"-1*20 5*8 12*3\"), solid = which tile numbers stop a physics body as \"1,3,5-9\" (empty means scenery only). The control's bounds follow columns*tileWidth by rows*tileHeight, whatever is sent for them. Only the tiles inside the view are drawn, so a 256x256 map costs the same as a small one, and solid tiles are collided against per body rather than as separate controls. Scripts use ui.getTile(id,column,row) (-1 off the grid), ui.setTile(id,column,row,index), ui.fillTiles(id,column,row,width,height,index), ui.tileAt(id,x,y) -> {column,row,tile} and ui.tileSize(id) -> {columns,rows,tileWidth,tileHeight}. A body that hits the map gets a collide event with the tilemap's ID. "
            + "Rendering and shaders (web): where WebGL2 is available, tilemap tiles, particles and plain sprites/images are drawn by a batched layer — one draw call per texture instead of one per instance — and composited into the canvas at the point in the draw order where they belong, so nothing changes places. A control needing a fill, border, corner radius, a parent panel or a disabled dim stays on canvas2D, and everything falls back to canvas2D when WebGL2 is missing. Measured: 20000 particles cost 2.5 ms against 8.4 ms on canvas2D, and the particle pool rises from 2000 to 50000 when the batch is there. upsert_shader uses key=shader ID and source=a GLSL ES 3.00 fragment shader (it must start with \"#version 300 es\"); delete_shader uses key. A screen runs one with upsert_screen data={shader:\"id\"}. The shader gets u_scene (what the layer drew), u_resolution, u_time in seconds, and any \"uniform float u_name\" a script sets with ui.setShaderValue(name, number). A shader that will not compile is reported in the log and dropped, costing the effect rather than the screen. "
            + "Typefaces: element font is minecraft:default|minecraft:uniform|minecraft:alt (all Minecraft has), one of the built-in web families web:sans|web:serif|web:mono|web:rounded|web:condensed|web:display|web:handwriting, or a font file in the project as projectid:fonts/name.ttf (.ttf, .otf, .woff2, .woff, up to 8 MiB, imported through the editor). Anything but the three minecraft: ones is web and desktop only and is reported for Minecraft. An unknown font name is a validation error rather than a silent fallback. "
            + "Pixel art: pixel_art draws images (new: width, height, frames, newName; or edit image) with commands such as grid {rows:['..RR..'], palette:{'R':'#FF0000'}}, line, rect, ellipse, fill, layers and groups (add_layer, add_group, set_layer, move_layer), frames (add_frame with copyOf); it saves a transparent PNG (frames side by side as a sprite sheet) plus its layers, as one Undo, and returns the texture ID to use as a control texture. read_pixel_art shows any image as a text grid and a preview PNG. "
            + "Sprites: after pixel_art makes frames, sprite_sheet sets a sprite control's texture, frameWidth/frameHeight and clips [{name, frames, fps, once}] (frames are checked against the sheet) and playing; read_sprite_sheet reports the sheet grid. "
            + "Building a game (web & desktop): use the engine's parts before writing your own. Entities: ui.spawn copies of a template control (each runs the template's events as itself), ui.seek/ui.separate/paths for movers and crowds, ui.despawn. Collision: body/collider on controls and solid tile numbers on a tilemap, with collide/trigger events and ctx.physics.touching, raycast, canSee and findPath. Scrolling rooms: a camera control (the screen's view; move it with ui.setPosition, attach HUD controls to it). Sprite states: state graphs. Rooms: separate screens, with shared progress in game variables (set_project data={gameVariables:{score:'0',best:'0'}, savedVariables:['best']}: they work like screen variables, keep their value when another screen opens, and saved ones come back next visit), since screen variables start over when a screen opens. "
            + "Navigation: an open_ui action on any event (click, tick, collide, trigger_enter...) opens a screen everywhere. Client scripts may call ctx.ui.open('screen') in web & desktop projects only; in a project made for minecraft or both, a client script can't switch screens (use an open_ui action, or a server script's ui.open). "
            + "Ticking: the screen's tick event and every control's own tick event run each tickInterval (spawned copies don't tick). Movement components (character_controller, topdown_mover, follower) put their script on their own control's tick, so several work side by side and the screen's tick stays free. A kinematic body given a velocity (ui.setVelocity) moves by it and stops against static bodies, colliders and solid tiles; one moved by setPosition or an animation goes where it's put. "
            + "Script state: each event runs the script from the top unless the project keeps script state. set_project data={keepScriptState:true} (made for web only; new projects have it on) runs each script's top level once and then only the event's function, so top-level variables (let score = 0) last between events and across screens until the game starts over or the script is edited; ctx/ui at the top level are the current event's. Without it (and always for minecraft or both), keep state in ctx.state (strings, per screen) or a global object. validate_project advises when a kept-state script uses ctx/ui outside a function, because that line then runs once. "
            + "Saved games (web & desktop): ctx.save.get(key) (text, '' when missing), set(key, text), has(key), keys(), remove(key), clear(). Text only (JSON.stringify objects), keys 1-100 characters, 512 KB per game; kept in the browser under the game's ID (host.js save.load/save.store can keep them elsewhere), and a failed script run saves nothing. Minecraft has no saves; validate_project reports ctx.save for projects made for Minecraft. "
            + "Project ID: changing it (set_project id) moves the project's pictures, sounds and fonts and updates textures, fonts, Sound controls, change_texture and play_sound actions, particles and leaderboard pages. Scripts aren't rewritten: validate_project advises on each script still naming a file by the old ID. "
            + "Arcadia details: a game's title, description, genres, controls, videos, cover, screenshots and leaderboard can be edited on the Arcadia website. arcadia_publish check reports detailsChanged when they were; the person chooses, when publishing, whether to keep Arcadia's (the default) or use the project's. Never choose for them. detailsChanged.leaderboard holds the question they'll be asked when the clash is over having a leaderboard at all (one on the website and none in the project, or turned off on the website and kept in the project). With leaderboard false the game is published with no leaderboard on purpose (\"scores\": false in game.json, no leaderboard page); leaderboardPage \"standard\" stops using a page of the project's own. "
            + "Limits: a web or desktop screen holds up to 16000 controls (Minecraft 512). One script run may make 100000 screen changes (every ctx.ui call and ctx.state.set counts; loops and maths don't) in web & desktop projects, 128 in projects made for minecraft or both; going over drops all of that run's changes with an error, so spread big jobs over ticks. Measured cost is about 0.4-0.8 microseconds a change, so a tick script at 60 fps should stay near 10000-20000. Each run has 2 seconds. Labels are one line: longer text is cut to fit, so use several labels (or a tilemap font) for paragraphs. validate_project also returns advice, which blocks nothing: past 4000 controls it reports roughly what drawing that screen costs a frame, since controls with text cost about 2.6x a plain one. "
            + "Teaching the person: when they ask how to do something in the editor, the tutorial tool can point at it (highlight a menu:<command>, toolbar:<command>, panel:<id>, toolbox:<type>, element:<id>, property:<label> or text:<words>; tutorial targets lists them), show a notice, or open a step-by-step tutorial window whose steps tick off by themselves (checks such as {kind:'element', element:'play'}). Prefer pointing and a short tutorial over long written directions. "
            + "Testing: preview_control script runs JavaScript on the open preview, input holds the game's inputs for some ms (walk a character), tap presses at x,y (buttons, ctx.input.pointer()), capture with value game gives the game area only, wait lets physics/animations/timers run, state reports live element bounds and variables. Screen events tick (tickInterval ms) and key (value = key name, ctx.repeat when held) are client-only."
    });
}
